/**
 * Shared share-card image (spec §11).
 *
 * Next merges `metadata` shallowly: a page that declares its own `openGraph`
 * replaces the parent's whole object, images included. So every page that sets
 * `openGraph` must spread these in rather than relying on app/layout.tsx.
 *
 * The file is generated by scripts/generate-og-image.mjs from the brand logo —
 * edit the script, not public/og.png. Paths stay relative; `metadataBase` in
 * app/layout.tsx resolves them to absolute URLs, which every unfurler requires.
 */
const OG_IMAGE = {
  url: "/og.png",
  width: 1200,
  height: 630,
  alt: "Paelon Memorial Hospital",
  type: "image/png",
};

/** Spread into any page's `openGraph`. */
export const OG_IMAGES = [OG_IMAGE];

/** Spread into any page's `twitter`. */
export const TWITTER_IMAGES = [OG_IMAGE.url];

/**
 * Deep link to Google's source preferences tool for this site.
 *
 * Google offers three implementations. This is the deeplink one, deliberately:
 * the recommended `news.google.com/swg/js/v1/publisher.js` button is a
 * third-party script on a content page, which the §13 budgets (initial JS
 * < 150 KB gzipped, TBT < 150ms) have no room for and CLAUDE.md rules out of
 * the critical path. The deeplink is a plain anchor — no script, no cookie, and
 * it works with JavaScript off. The end-user flow is the same either way.
 *
 * Returns `null` when the configured site URL has no public host (localhost in
 * development), because there is no domain a reader could add.
 *
 * @param siteUrl absolute site origin, normally `NEXT_PUBLIC_SITE_URL`
 */
export function preferredSourceUrl(siteUrl: string): string | null {
  let host: string;

  try {
    host = new URL(siteUrl).hostname;
  } catch {
    return null;
  }

  // Only domains and subdomains are eligible; a hostless or loopback origin is
  // not something Google's tool can resolve.
  if (!host.includes(".") || host === "127.0.0.1" || host === "[::1]") {
    return null;
  }

  return `https://www.google.com/preferences/source?q=${encodeURIComponent(host)}`;
}

/**
 * `MedicalOrganization` JSON-LD (spec §11: "on the homepage and About page").
 *
 * One builder rather than a literal per page. Two hand-written copies of the
 * same claims about the hospital drift the moment one page is edited, and
 * structured data that disagrees with itself across a site is worse than one
 * copy — a crawler has no way to tell which is current.
 *
 * TODO(seed): no logo, `sameAs` profiles, or verified opening hours are
 * available yet, so they are omitted rather than guessed. Invalid structured
 * data is worse than absent structured data.
 *
 * @param siteUrl absolute site origin, normally `NEXT_PUBLIC_SITE_URL`
 * @param location the branch whose address and phone front the site, or null
 */
export function medicalOrganizationLd(
  siteUrl: string,
  location: OrganizationLocation | null,
): Record<string, unknown> {
  return {
    "@context": "https://schema.org",
    "@type": "MedicalOrganization",
    name: "Paelon Memorial Hospital",
    url: siteUrl,
    description:
      "Family-centered medical care in Lagos, from paediatrics to fertility and general practice.",
    ...(location
      ? {
          telephone: location.phone,
          address: {
            "@type": "PostalAddress",
            streetAddress: location.address_line_1,
            addressLocality: location.city,
            addressRegion: location.state,
            addressCountry: location.country,
          },
        }
      : {}),
  };
}

/**
 * The branch fields the organisation schema needs. A structural subset of
 * `Location` in `lib/content.ts`, declared here so this module stays free of a
 * value import from the content layer.
 */
export interface OrganizationLocation {
  phone: string;
  address_line_1: string;
  city: string;
  state: string;
  country: string;
}
